const CORE_FILES = ['./', 'index.html', 'manifest.webmanifest'];
const HKEY = '__hashes__';

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(CORE);
    await c.addAll(CORE_FILES.map(u => new Request(u, { cache: 'reload' })));
    const m = await caches.open(MEDIA_C);
    const old = await m.match(HKEY).then(r => r ? r.json() : {}).catch(() => ({}));
    const need = Object.keys(MEDIA).filter(p => old[p] !== MEDIA[p]);
    const done = Object.assign({}, old);
    // 6本ずつ取る。失敗した絵は後で開いた時に取り直す。
    for (let i = 0; i < need.length; i += 6) {
      await Promise.all(need.slice(i, i + 6).map(async p => {
        try {
          const r = await fetch(new Request(p, { cache: 'reload' }));
          if (r.ok) { await m.put(p, r); done[p] = MEDIA[p]; }
        } catch (_) {}
      }));
    }
    for (const p of Object.keys(done)) if (!(p in MEDIA)) { await m.delete(p); delete done[p]; }
    await m.put(HKEY, new Response(JSON.stringify(done), { headers: { 'Content-Type': 'application/json' } }));
  })());
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('core-') && k !== CORE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('message', e => { if (e.data === 'skip') self.skipWaiting(); });

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return; // Google ログイン・Firebase・フォントは触らない
  const path = url.pathname.slice(new URL(self.registration.scope).pathname.length);
  if (req.mode === 'navigate' || path === '' || path === 'index.html' || path === 'manifest.webmanifest') {
    e.respondWith((async () => {
      const c = await caches.open(CORE);
      const key = req.mode === 'navigate' ? 'index.html' : (path || 'index.html');
      return (await c.match(key)) || fetch(req);
    })());
    return;
  }
  if (path in MEDIA) {
    e.respondWith((async () => {
      const m = await caches.open(MEDIA_C);
      const hit = await m.match(path);
      if (hit) return hit;
      const r = await fetch(req);
      if (r.ok) m.put(path, r.clone());
      return r;
    })());
  }
});
